with not_flagged as (select s.* from sessions s where not exists (select 1 from web_events ch where ch.session_id = s.id and ch.event_type not in ('search', 'add_to_cart'))) select browser, country, count(*) as event_count, sort_array(collect_set(browser)) as browser_list, count(distinct device) as distinct_devices, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as duration_min from not_flagged group by browser, country having count(distinct device) < 1000;
